SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRANSACTION;
DECLARE @Category UNIQUEIDENTIFIER=NEWID(),@Brand UNIQUEIDENTIFIER=NEWID(),@Unit UNIQUEIDENTIFIER=NEWID(),@Product UNIQUEIDENTIFIER=NEWID(),@Type UNIQUEIDENTIFIER=NEWID(),@Warehouse UNIQUEIDENTIFIER=NEWID(),@Supplier UNIQUEIDENTIFIER=NEWID(),@Balance UNIQUEIDENTIFIER=NEWID(),@Purchase UNIQUEIDENTIFIER,@Item UNIQUEIDENTIFIER;
INSERT master.ProductCategories(ProductCategoryId,CategoryCode,CategoryName,DisplayOrder,CreatedOn,IsActive,IsDeleted)VALUES(@Category,'PUR-VERIFY-CAT','Purchase Verification',1,SYSUTCDATETIME(),1,0);INSERT master.Brands(BrandId,BrandCode,BrandName,CreatedOn,IsActive,IsDeleted)VALUES(@Brand,'PUR-VERIFY-BRAND','Purchase Verification',SYSUTCDATETIME(),1,0);INSERT master.UnitsOfMeasure(UnitId,UnitCode,UnitName,ShortName,DecimalPlaces,CreatedOn,IsActive,IsDeleted)VALUES(@Unit,'PUR-VERIFY-EA','Purchase Verification Each','EA',0,SYSUTCDATETIME(),1,0);INSERT master.Products(ProductId,ProductCode,Barcode,ProductName,CategoryId,BrandId,UnitId,GSTPercentage,PurchasePrice,SellingPrice,MRP,MinimumStock,MaximumStock,ReorderLevel,IsBatchManaged,IsSerialManaged,CreatedOn,IsActive,IsDeleted)VALUES(@Product,'PUR-VERIFY-PRODUCT','8911111111111','Purchase Verification Product',@Category,@Brand,@Unit,18,50,80,100,0,100,5,0,0,SYSUTCDATETIME(),1,0);INSERT inventory.WarehouseTypes(WarehouseTypeId,TypeCode,TypeName)VALUES(@Type,'PUR-VERIFY','Purchase Verification');INSERT inventory.Warehouses(WarehouseId,WarehouseCode,WarehouseName,WarehouseTypeId,CreatedBy)VALUES(@Warehouse,'PUR-VERIFY-WH','Purchase Verification Warehouse',@Type,'verification');INSERT purchase.Suppliers(SupplierId,SupplierCode,SupplierName,SupplierType,Currency,CreatedBy)VALUES(@Supplier,'PUR-VERIFY-SUP','Purchase Verification Supplier','Distributor','INR','verification');INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,QuantityOnHand,AverageCost,LastPurchaseCost,CreatedBy)VALUES(@Balance,@Product,@Warehouse,10,50,50,'verification');
DECLARE @Items NVARCHAR(MAX)=CONCAT('[{"ProductId":"',CONVERT(NVARCHAR(36),@Product),'","Barcode":"8911111111111","Quantity":2,"FreeQuantity":1,"PurchasePrice":100,"MRP":140,"SellingPrice":120,"DiscountPercentage":0,"DiscountAmount":0,"GSTPercentage":18}]');DECLARE @Created TABLE(PurchaseInvoiceId UNIQUEIDENTIFIER,InvoiceNumber NVARCHAR(50),GrandTotal DECIMAL(18,2),PaidAmount DECIMAL(18,2),BalanceAmount DECIMAL(18,2),Status NVARCHAR(20));INSERT @Created EXEC purchase.Purchase_Post @SupplierId=@Supplier,@SupplierInvoiceNo='VERIFY-001',@InvoiceDate='2026-08-06',@WarehouseId=@Warehouse,@ItemsJson=@Items,@ExpensesJson='[{"ExpenseType":"FREIGHT","Amount":30,"IsTaxable":false}]',@PaymentsJson='[{"MethodCode":"CASH","Amount":100}]',@CreatedBy='verification';SELECT @Purchase=PurchaseInvoiceId FROM @Created;SELECT @Item=PurchaseItemId FROM purchase.PurchaseInvoiceItems WHERE PurchaseInvoiceId=@Purchase;
IF(SELECT QuantityOnHand FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance)<>13 THROW 51200,'Purchase did not receive paid and free stock.',1;IF ABS((SELECT AverageCost FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance)-56.1538)>.0001 THROW 51200,'Weighted landed average cost is incorrect.',1;IF(SELECT LastPurchaseCost FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance)<>100 THROW 51200,'Last purchase cost was not updated.',1;IF purchase.PurchaseOutstanding(@Purchase)<>166 THROW 51200,'Supplier outstanding is incorrect.',1;
DECLARE @Returns NVARCHAR(MAX)=CONCAT('[{"PurchaseItemId":"',CONVERT(NVARCHAR(36),@Item),'","Quantity":1}]');EXEC purchase.Purchase_Return @PurchaseInvoiceId=@Purchase,@ItemsJson=@Returns,@Reason='Verification return',@CreatedBy='verification';IF(SELECT QuantityOnHand FROM inventory.InventoryBalances WHERE InventoryBalanceId=@Balance)<>12 THROW 51200,'Purchase return did not deduct stock.',1;IF ABS(purchase.PurchaseOutstanding(@Purchase)-87.33)>.01 THROW 51200,'Supplier return adjustment is incorrect.',1;
SELECT i.InvoiceNumber,i.GrandTotal,i.PaidAmount,purchase.PurchaseOutstanding(i.PurchaseInvoiceId)Outstanding,b.QuantityOnHand,b.AverageCost,b.LastPurchaseCost,(SELECT COUNT(*)FROM inventory.InventoryValuation WHERE ProductId=@Product)ValuationRows,(SELECT COUNT(*)FROM purchase.PurchaseReturns WHERE PurchaseInvoiceId=@Purchase)ReturnRows FROM purchase.PurchaseInvoices i JOIN inventory.InventoryBalances b ON b.InventoryBalanceId=@Balance WHERE i.PurchaseInvoiceId=@Purchase;ROLLBACK TRANSACTION;
